const deals = $input.all().map(i => i.json);
if (!deals.length || !deals[0].id) return [];

const results = [];
const now = Date.now();

for (const deal of deals) {
  const lastActivity = deal.last_activity ? new Date(deal.last_activity).getTime() : 0;
  const daysSinceActivity = (now - lastActivity) / (1000 * 60 * 60 * 24);
  const createdAt = new Date(deal.created_at).getTime();
  const daysInPipeline = (now - createdAt) / (1000 * 60 * 60 * 24);

  let newStage = deal.stage;
  let action = null;
  let reason = null;
  let newProbability = deal.probability;

  // Auto-advance rules
  switch (deal.stage) {
    case 'prospecting':
      if (deal.recent_activities >= 3 && deal.lead_score >= 40) {
        newStage = 'qualification';
        newProbability = 20;
        reason = 'High engagement + lead score threshold';
        action = 'stage_advanced';
      }
      break;

    case 'qualification':
      if (deal.last_activity_type === 'meeting_scheduled' || deal.last_activity_type === 'demo_completed') {
        newStage = 'proposal';
        newProbability = 40;
        reason = 'Meeting/demo completed';
        action = 'stage_advanced';
      } else if (daysSinceActivity > 14) {
        action = 'stale_warning';
        reason = `No activity for ${Math.round(daysSinceActivity)} days`;
      }
      break;

    case 'proposal':
      if (deal.last_activity_type === 'proposal_viewed' || deal.last_activity_type === 'proposal_signed') {
        newStage = 'negotiation';
        newProbability = 60;
        reason = 'Proposal viewed/signed';
        action = 'stage_advanced';
      } else if (daysSinceActivity > 7) {
        action = 'follow_up_needed';
        reason = 'Proposal sent but no response';
      }
      break;

    case 'negotiation':
      if (deal.last_activity_type === 'contract_signed') {
        newStage = 'closed_won';
        newProbability = 100;
        reason = 'Contract signed';
        action = 'deal_won';
      } else if (daysSinceActivity > 10) {
        action = 'escalation_needed';
        reason = 'Negotiation stalled';
      }
      break;
  }

  // Stale deal detection
  if (!action && daysSinceActivity > 30 && deal.stage !== 'prospecting') {
    action = 'at_risk';
    reason = `Deal stale for ${Math.round(daysSinceActivity)} days`;
    newProbability = Math.max(5, deal.probability - 20);
  }

  // Expected close date passed
  if (deal.expected_close_date && new Date(deal.expected_close_date) < new Date() && !action) {
    action = 'overdue';
    reason = 'Expected close date has passed';
  }

  if (action) {
    results.push({
      json: {
        deal_id: deal.id,
        deal_name: deal.deal_name,
        deal_value: deal.deal_value,
        contact_email: deal.email,
        contact_name: `${deal.first_name} ${deal.last_name}`,
        company: deal.company,
        current_stage: deal.stage,
        new_stage: newStage,
        new_probability: newProbability,
        action: action,
        reason: reason,
        assigned_to: deal.assigned_to,
        client_id: deal.client_id,
        days_in_pipeline: Math.round(daysInPipeline),
        days_since_activity: Math.round(daysSinceActivity)
      }
    });
  }
}

return results;
